def route_playback_urls(cdn_registry, user_asn: str, title_id: str) -> list[str]:
    healthy_edges = cdn_registry.find_edges_for_asn(user_asn, title_id)
    if not healthy_edges:
        return cdn_registry.fallback_ixp_edges(title_id)
    return [e.signed_url(title_id) for e in healthy_edges[:3]]

def validate_ingest_manifest(expected_sha256: str, actual_sha256: str) -> None:
    if expected_sha256 != actual_sha256:
        raise ValueError('Studio master checksum mismatch; aborting transcode DAG')

def select_titles_for_edge_fill(catalog_scores: list[dict], disk_budget_tb: float) -> list[str]:
    ranked = sorted(catalog_scores, key=lambda x: x['predicted_views'], reverse=True)
    selected, used_tb = [], 0.0
    for item in ranked:
        if used_tb + item['size_tb'] <= disk_budget_tb:
            selected.append(item['title_id'])
            used_tb += item['size_tb']
    return selected

def score_edge_candidate(edge: dict) -> float:
    if edge['nic_util'] > 0.90 or not edge['healthy']:
        return -1.0
    return (1.0 - edge['nic_util']) * 0.6 + (1.0 / (1.0 + edge['rtt_ms'])) * 0.4

def upsert_watch_progress(cassandra, profile_id: str, title_id: str, pos_sec: int, ts_ms: int) -> None:
    cassandra.execute(
        'INSERT INTO watch_progress (profile_id, title_id, pos_sec, updated_ms) '
        'VALUES (%s, %s, %s, %s) USING TIMESTAMP %s',
        (profile_id, title_id, pos_sec, ts_ms, ts_ms * 1000)
    )

def verify_edge_token(secret: bytes, path: str, expires: int, sig: str, now: int) -> bool:
    if now > expires:
        return False
    expected = hmac.new(secret, f'{path}:{expires}'.encode(), 'sha256').hexdigest()
    return hmac.compare_digest(expected, sig)

def compute_rebuffer_ratio(rebuffer_ms: int, play_ms: int) -> float:
    total = rebuffer_ms + play_ms
    return (rebuffer_ms / total) if total > 0 else 0.0
